import{z as B,x as s,o,c as p,q as n,j as l,D as t,d as E,s as r,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"去优化","description":"","frontmatter":{"title":"去优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deoptimization.md","filePath":"cs/deoptimization.md","lastUpdated":1791063341000}'),d={name:"cs/deoptimization.md"};function C(m,a,D,c,h,u){const i=s("Mermaid");return o(),p("div",null,[a[2]||(a[2]=n('<h1 id="去优化" tabindex="-1">去优化 <a class="header-anchor" href="#去优化" aria-label="Permalink to &quot;去优化&quot;">​</a></h1><div class="epigraph"><p>投机编译假设类型、别名、类层次；失败时必须把 native 帧翻译回解释器（或低层 JIT）状态，而不能假装没发生过。</p><footer>—— 据 Hölzle, Chambers and Ungar, Debugging Optimized Code with Dynamic Deoptimization, 1992；HotSpot 去优化说明整理</footer></div><p>上一课<a href="/cs/inline-caching">内联缓存</a> 在失配时要退出投机码。缺口是 <strong>deopt</strong>：映射寄存器与 spill 到字节码栈、PC、锁状态。本课钉为什么必须、元数据，类型反馈下一课是投机的来源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内联+类型假设后，CFG 不再对应源方法。失败：类加载打破 CHA、IC 失配、守卫失败。必须恢复：解释器能继续。缺口是<strong>栈重写与副作用已发生</strong>（不能回滚 IO），只恢复虚拟机状态。</p><p><span class="marginnote">术语翻译：去优化就是「把跑在快道上、但假设已被打破的代码，安全地搬回慢道」。搬家不靠重算，靠编译器预先留下的映射表，把寄存器与栈槽翻译回解释器认识的字节码栈、PC 与锁状态，从失败点无缝继续。</span></p><p>OSR（on-stack replacement）是反方向：解释器帧换成 compiled 帧。</p><h3 id="去优化不是「反编译」" tabindex="-1">去优化不是「反编译」 <a class="header-anchor" href="#去优化不是「反编译」" aria-label="Permalink to &quot;去优化不是「反编译」&quot;">​</a></h3><p>不是从机器码还原源。是编译器预先留下的映射表：<code>pc → 字节码索引 + 位置列表</code>。与 DWARF 同类，服务 VM 而非 GDB。</p><p><span class="marginnote">Hölzle et al. 1992 PLDI。HotSpot Deoptimization。本课不写全部帧描述符格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译时发 deopt 元数据。运行时：save 寄存器、walk 内联帧链、物化对象（逃逸分析撤销）、跳入解释器。延迟去优化：标记代码为非入口，现有帧在安全点再转。</p>',12)),(o(),l(A,null,{default:t(()=>[r(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E5%AE%88%E5%8D%AB%20%2F%20IC%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20MAP%5B%22%E5%B8%A7%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20MAP%20--%3E%20INT%5B%22%E9%87%8D%E5%BB%BA%E8%A7%A3%E9%87%8A%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20INT%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与"),e("a",{href:"/cs/escape-analysis"},"逃逸分析"),E("：栈化对象在 deopt 时要重新堆分配（物化）。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"安全点：GC 与 deopt 只能在约定点停，否则映射不存在。不要在任意机器指令去优化。锁：膨胀、消除的锁要恢复。",-1)),a[6]||(a[6]=e("p",null,"把投机代码的整个生命周期摆出来，deopt 只是其中一环，之后还要回到编译策略上：",-1)),(o(),l(A,null,{default:t(()=>[r(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A7%A3%E9%87%8A%E6%89%A7%E8%A1%8C%EF%BC%9A%E6%94%B6%E9%9B%86%E7%B1%BB%E5%9E%8B%20profile%22%5D%20--%3E%20HOT%5B%22%E7%83%AD%E7%82%B9%EF%BC%9AJIT%20%E7%BC%96%E8%AF%91%E5%B9%B6%E5%86%85%E8%81%94%22%5D%0A%20%20HOT%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%8A%95%E6%9C%BA%E4%BB%A3%E7%A0%81%EF%BC%9A%E5%AE%88%E5%8D%AB%E5%9C%A8%E5%9C%BA%22%5D%0A%20%20HOT%20--%3E%7C%22%E5%81%87%E8%AE%BE%E4%B8%80%E7%9B%B4%E6%88%90%E7%AB%8B%22%7C%20OK%5B%22%E6%8C%81%E7%BB%AD%E5%BF%AB%E9%80%9F%E6%89%A7%E8%A1%8C%22%5D%0A%20%20RUN%20--%3E%7C%22%E5%AE%88%E5%8D%AB%E5%A4%B1%E8%B4%A5%22%7C%20DEOPT%5B%22%E5%8E%BB%E4%BC%98%E5%8C%96%EF%BC%9A%E6%8C%89%E6%98%A0%E5%B0%84%E8%A1%A8%E9%87%8D%E5%BB%BA%E8%A7%A3%E9%87%8A%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20DEOPT%20--%3E%20INT2%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%E7%BB%A7%E7%BB%AD%EF%BC%8Cprofile%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20INT2%20--%3E%20RECOMP%5B%22%E5%86%8D%E7%BC%96%E8%AF%91%EF%BC%9A%E6%94%B6%E6%95%9B%E5%81%87%E8%AE%BE%E6%88%96%E6%94%BE%E5%BC%83%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">直觉类比：投机编译像外卖员猜「你家大门常开」径直送到门口——平时省去按门铃（类型检查），一旦猜错，守卫（门铃）响了只好退回前台重走流程（去优化）。注意：已经塞进门缝的东西（已发生的写操作、IO）收不回来，重走的是「接下来的路」，不是「来时的路」。</span></p><p><span class="marginnote">常见误区：初学者容易把 deopt 当成「反编译」或「回滚」。它既不从机器码还原源码（只是查编译期留下的映射表），也不能撤销已执行的副作用——只恢复虚拟机状态让程序继续。另外，deopt 本该稀少；若某段代码频繁去优化，说明它太投机，正确的反应是降级假设而不是忍着。</span></p><p>性能：deopt 应稀。频繁则代码太投机，要降级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分层编译阈值。后课默认：投机必须可逆到 VM 状态。下一课类型反馈：给投机提供数据。</p><p>也不把 deopt 当异常 unwind 的别名（可共用展开，语义不同）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去优化：投机 native → 解释器/低层状态。</li><li>靠编译期映射，不是反编译。</li><li>物化、锁、安全点是实现难点。</li><li>出处：Hölzle, Chambers and Ungar, 1992；HotSpot。</li></ul>',8))])}const _=B(d,[["render",C]]);export{f as __pageData,_ as default};
